CREATE Proc [dbo].[TruncateDatabseTransection]  @Type as nvarchar(50), @Shift as nvarchar(50) as   if  @Type = 'Transection' begin if @Shift = 'All'  begin Delete from dbo.Dine_In_Order Delete from dbo.Discount Delete from dbo.Ent Delete from dbo.Item_Delete Delete from dbo.Item_Less Delete from dbo.Order_Detail Delete from dbo.Order_Payment Delete from dbo.OrderKot Delete from dbo.Shift_Opening Delete from dbo.TableMerge update Tables set Table_status = 'Close' DELETE FROM CASHDROP DELETE FROM SHIFTAMOUNT DELETE FROM  PRODUCTSALEMASTER DELETE FROM PRODUCTSALEDETAIL delete from Gl where Vn like 'SAL-%' delete from POSSALERETURNMASTER delete from POSSALERETURNDETAIL delete from RiderCashFloat delete from DealsOnSpotItems delete from tempkeys delete  from dbo.TempDealsOnSpotItems UPDATE TBL_USER SET LOGINSTATUS = 0 delete from dbo.AdvanceBooking delete from CustomerLedgerAdvBooking delete from BuffetBooking delete from customerReciptMaster delete from customerReciptdetail delete from dbo.OrderStatusTime delete from dbo.LoginStatus end else  begin  DELETE order_payment FROM order_payment INNER JOIN Dine_In_order ON order_payment.z_number = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift DELETE Order_Detail FROM Order_Detail INNER JOIN Dine_In_order ON Order_Detail.z_number = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift  DELETE Item_Less  FROM Item_Less INNER JOIN Dine_In_order ON Item_Less.z_num = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift DELETE Item_Delete  FROM Item_Delete INNER JOIN Dine_In_order ON Item_Delete.z_num = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift   DELETE Ent  FROM Ent INNER JOIN Dine_In_order ON Ent.z_num = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift   DELETE Discount  FROM Discount INNER JOIN Dine_In_order ON Discount.z_num = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift   DELETE OrderKot  FROM OrderKot INNER JOIN Dine_In_order ON OrderKot.OrderKey = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift   DELETE POSSALERETURNDETAIL  FROM POSSALERETURNDETAIL INNER JOIN POSSALERETURNMASTER ON POSSALERETURNMASTER.Sid = POSSALERETURNDETAIL.Sid WHERE POSSALERETURNMASTER.ShiftNo = @Shift   DELETE POSSALERETURNMASTER  FROM POSSALERETURNMASTER INNER JOIN Dine_In_order ON POSSALERETURNMASTER.ShiftNo = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift   DELETE from dbo.TableMerge  where Z_number = @Shift   DELETE FROM CASHDROP  where Z_number = @Shift   DELETE from RiderCashFloat  WHERE ShiftNo = @Shift   DELETE FROM SHIFTAMOUNT  where Z_number = @Shift   DELETE tempkeys  FROM tempkeys INNER JOIN Dine_In_order ON tempkeys.OrderKey = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift   DELETE DealsOnSpotItems from DealsOnSpotItems INNER JOIN Dine_In_order ON DealsOnSpotItems.Order_Key = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift   DELETE TempDealsOnSpotItems from TempDealsOnSpotItems INNER JOIN Dine_In_order ON TempDealsOnSpotItems.Order_Key = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift  DELETE AdvanceBooking FROM AdvanceBooking INNER JOIN Dine_In_order ON AdvanceBooking.ShiftNo = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift  DELETE BuffetBooking FROM BuffetBooking INNER JOIN Dine_In_order ON BuffetBooking.Order_Key = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift  DELETE PRODUCTSALEDETAIL  FROM PRODUCTSALEDETAIL INNER JOIN PRODUCTSALEMASTER ON PRODUCTSALEMASTER.PMID = PRODUCTSALEDETAIL.PMID WHERE PRODUCTSALEMASTER.znumber = @Shift   DELETE PRODUCTSALEMASTER  FROM PRODUCTSALEMASTER INNER JOIN Dine_In_order ON PRODUCTSALEMASTER.znumber = Dine_In_order.z_number WHERE Dine_In_order.z_number = @Shift   DELETE OrderStatusTime  FROM OrderStatusTime INNER JOIN Dine_In_order ON OrderStatusTime.Order_Key = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift   DELETE customerReciptdetail  FROM customerReciptdetail INNER JOIN customerReciptMaster ON customerReciptdetail.CustRid = customerReciptMaster.CustRid INNER JOIN CustomerLedgerAdvBooking ON customerReciptMaster.PaymentNo = CustomerLedgerAdvBooking.VN WHERE CustomerLedgerAdvBooking.ShiftNo = @Shift   DELETE customerReciptMaster  FROM customerReciptMaster  INNER JOIN CustomerLedgerAdvBooking ON customerReciptMaster.PaymentNo = CustomerLedgerAdvBooking.VN WHERE CustomerLedgerAdvBooking.ShiftNo = @Shift    DELETE CustomerLedgerAdvBooking  WHERE ShiftNo = @Shift   DELETE BuffetBooking  FROM BuffetBooking INNER JOIN Dine_In_order ON BuffetBooking.Order_Key = Dine_In_order.Order_Key WHERE Dine_In_order.z_number = @Shift   Delete from dbo.Dine_In_Order where Z_number = @Shift  Delete from dbo.Shift_Opening where Z_report_number = @Shift  end  end  else  if @Type = 'Settings' begin delete from DepartmentPOS delete from CategoryPOS delete from CategoryTiltAssign  Delete from ItemPOS  delete from ItemComments  delete from Deals  delete from DealsOnSpot  delete from Rider delete from waiter delete from tables Update tax set isApplicable = 0,tax_type = 'Exclusive',tax_amount = '17',Tax = 'GST' Update ServiceCharges set [Percent] = 0,isApplicable = 0,AppylOnCovers = 0,OnCovers = 0,ApplyOnAmount = 0,OnAmount = 0 delete from Shift_User delete from Reports_Settings delete from OrderServedTime  delete from Printer_Setup delete from CashDrawer Update CompanySetup set CompanyName = '',Address = '',Email = '' delete from SheeshaTime update tbl_user set loginstatus = 0 delete from SmsSetting delete from tbl_user where username <> 'admin' delete from Tilt end